from heapq import heappush, heappop

def solve(n, edges, s, t):
    if s == t:
        return 0
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))

    dist = [float('inf')] * n
    dist[s] = 0
    heap = [(0, s)]

    while heap:
        d, u = heappop(heap)
        if u == t:
            return d
        if d > dist[u]:
            continue
        for v, w in adj[u]:
            if dist[v] > d + w:
                dist[v] = d + w
                heappush(heap, (dist[v], v))

    return -1

