def solve(n, edges, s, t):
    if s == t:
        return 0
    from collections import deque
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))

    INF = float('inf')
    dist = [INF] * n
    dist[s] = 0
    q = deque([(s, 0)])

    while q:
        u, d = q.popleft()
        for v, w in adj[u]:
            if dist[v] > d + w:
                dist[v] = d + w
                q.append((v, dist[v]))

    return -1 if dist[t] == INF else dist[t]

