def solve(nums, k):
    def introselect(arr, k):
        def partition(arr, left, right, pivot_index):
            pivot = arr[pivot_index]
            arr[pivot_index], arr[right] = arr[right], arr[pivot_index]
            store_index = left
            for i in range(left, right):
                if arr[i] < pivot:
                    arr[store_index], arr[i] = arr[i], arr[store_index]
                    store_index += 1
            arr[right], arr[store_index] = arr[store_index], arr[right]
            return store_index

        def select(arr, left, right, k):
            if left == right:
                return arr[left]
            pivot_index = random.randint(left, right)
            pivot_index = partition(arr, left, right, pivot_index)
            if k == pivot_index:
                return arr[k]
            elif k < pivot_index:
                return select(arr, left, pivot_index - 1, k)
            else:
                return select(arr, pivot_index + 1, right, k)

        def quickselect(arr, left, right, k):
            while True:
                pivot_index = random.randint(left, right)
                pivot_index = partition(arr, left, right, pivot_index)
                if k == pivot_index:
                    return arr[k]
                elif k < pivot_index:
                    right = pivot_index - 1
                else:
                    left = pivot_index + 1

        def find_kth(arr, k):
            if len(arr) <= 10:
                return sorted(arr)[k - 1]
            pivot_index = random.randint(0, len(arr) - 1)
            pivot = arr[pivot_index]
            left = [x for x in arr if x < pivot]
            middle = [x for x in arr if x == pivot]
            right = [x for x in arr if x > pivot]
            if k <= len(left):
                return find_kth(left, k)
            elif k <= len(left) + len(middle):
                return pivot
            else:
                return find_kth(right, k - len(left) - len(middle))

        if k < 1 or k > len(nums):
            raise ValueError("k is out of bounds")
        if len(nums) <= 10:
            return sorted(nums)[k - 1]
        return find_kth(nums, k)
    return introselect(nums.copy(), k)

