            res = 0
            while idx > 0:
                res += self.tree[idx]
                idx -= idx & -idx
            return res

        def find_kth(self, k):
            idx = 0
            bit = 1
            while bit <= self.n:
                next_idx = idx + bit
                if next_idx <= self.n and self.query(next_idx) < k:
                    idx = next_idx
                bit <<= 1
            return idx

    ft = FenwickTree(max_rank)
    for num in nums:
        ft.update(rank[num], 1)

