    size = len(unique_vals)
    # Initialize Binary Indexed Tree
    class BIT:
        def __init__(self, size):
            self.N = size
            self.tree = [0] * (self.N + 1)

        def update(self, idx, delta):
            while idx <= self.N:
                self.tree[idx] += delta
                idx += idx & -idx

        def query(self, idx):
            res = 0
            while idx > 0:
                res += self.tree[idx]
                idx -= idx & -idx
            return res

    bit = BIT(size)
    # Populate BIT with frequencies
    for num in nums:
        idx = value_to_index[num]
        bit.update(idx, 1)

    # Binary search on the value space
    left, right = 0, size - 1
    while left < right:
        mid = (left + right) // 2
        val = unique_vals[mid]
        # Find how many elements are <= val
        count = bit.query(value_to_index[val])
        if count < k:
            left = mid + 1
        else:
            right = mid
    return unique_vals[left]

